<div class="poster">

  <!-- HEADER -->
  <div class="header">
    <div class="venue-badge">IEEE Symposium on Security and Privacy (S&P)</div>
    <h1>Bot Mitigation at Scale: How Modern Web Security Services Protect Scientific Publishing Platforms</h1>
    <div class="subtitle">An analysis of how challenge-based bot verification systems safeguard high-value academic web properties against automated threats — examining deployment on platforms serving millions of researchers worldwide</div>
  </div>

  <!-- 1. THREAT LANDSCAPE -->
  <div class="threat-section">
    <div class="section-title">
      <span class="num">1</span> The Bot Threat Landscape for Academic Publishers
    </div>
    <div class="threat-grid">
      <div class="threat-card">
        <div class="big-num">~47%</div>
        <div class="big-label">of all internet traffic<br>originated from bots (2024)</div>
      </div>
      <div class="threat-card">
        <div class="big-num">30%</div>
        <div class="big-label">of bot traffic classified<br>as malicious</div>
      </div>
      <div class="threat-card">
        <div class="big-num">1.2M</div>
        <div class="big-label">daily scraping attempts<br>before mitigation</div>
      </div>
    </div>
    <div class="threat-desc">
      Scientific publishing platforms host high-value intellectual property — peer-reviewed articles, supplementary datasets, and DOIs — making them prime targets for large-scale scraping, credential stuffing, and denial-of-service attacks. Academic publishers face a disproportionate share of scraping bots attempting to harvest full-text articles at scale.
    </div>
  </div>

  <!-- 2. PIPELINE -->
  <div class="pipeline-section">
    <div class="section-title">
      <span class="num">2</span> Challenge-Based Verification Pipeline
    </div>
    <div class="pipeline-flow">
      <div class="pipeline-stage">
        <div class="pipeline-connector" style="left:50%; width:50%;"></div>
        <div class="stage-circle">1</div>
        <div class="stage-name">Request Interception</div>
        <div class="stage-desc">Incoming HTTP request routed through CDN edge node</div>
        <div class="stage-time">&lt; 50 ms</div>
        <div class="pipeline-arrow">
          <svg viewBox="0 0 36 36" fill="none"><path d="M8 18h20M22 12l6 6-6 6" stroke="#38bdf8" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg>
        </div>
      </div>
      <div class="pipeline-stage">
        <div class="pipeline-connector"></div>
        <div class="stage-circle">2</div>
        <div class="stage-name">Threat Scoring</div>
        <div class="stage-desc">IP reputation, TLS fingerprint & behavioral signals evaluated</div>
        <div class="stage-time">~ 100 ms</div>
        <div class="pipeline-arrow">
          <svg viewBox="0 0 36 36" fill="none"><path d="M8 18h20M22 12l6 6-6 6" stroke="#22d3ee" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg>
        </div>
      </div>
      <div class="pipeline-stage">
        <div class="pipeline-connector"></div>
        <div class="stage-circle">3</div>
        <div class="stage-name">Challenge Issuance</div>
        <div class="stage-desc">JS or CAPTCHA challenge served if risk score exceeds threshold</div>
        <div class="stage-time">~ 500 ms</div>
        <div class="pipeline-arrow">
          <svg viewBox="0 0 36 36" fill="none"><path d="M8 18h20M22 12l6 6-6 6" stroke="#2dd4bf" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg>
        </div>
      </div>
      <div class="pipeline-stage">
        <div class="pipeline-connector"></div>
        <div class="stage-circle">4</div>
        <div class="stage-name">Verification Check</div>
        <div class="stage-desc">Client response validated; unique Ray ID assigned for tracing</div>
        <div class="stage-time">~ 200 ms</div>
        <div class="pipeline-arrow">
          <svg viewBox="0 0 36 36" fill="none"><path d="M8 18h20M22 12l6 6-6 6" stroke="#38bdf8" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg>
        </div>
      </div>
      <div class="pipeline-stage">
        <div class="stage-circle">5</div>
        <div class="stage-name">Access Grant</div>
        <div class="stage-desc">Verified user forwarded to origin server with session token</div>
        <div class="stage-time">&lt; 50 ms</div>
      </div>
    </div>
    <div class="pipeline-latency-bar">
      <span class="icon-shield">🛡️</span>
      <span>Total end-to-end latency for legitimate users: <strong>&lt; 2 seconds</strong> &nbsp;|&nbsp; Automated scripts lacking JS execution are <strong>blocked entirely</strong></span>
    </div>
  </div>

  <!-- 3. PERFORMANCE METRICS -->
  <div class="metrics-section">
    <div class="section-title">
      <span class="num">3</span> Performance and Security Outcomes
    </div>
    <div class="metrics-grid">
      <div class="metric-hero primary">
        <div class="metric-value">85%</div>
        <div class="metric-label">Reduction in Scraping Attempts</div>
        <div class="metric-detail">Within first 6 months of deployment</div>
      </div>
      <div class="metric-hero primary">
        <div class="metric-value">99.97%</div>
        <div class="metric-label">Platform Uptime Maintained</div>
        <div class="metric-detail">Even during bot surges exceeding 10× normal traffic</div>
      </div>
      <div class="metric-hero">
        <div class="metric-value">&lt; 0.3%</div>
        <div class="metric-label">Legitimate User Friction</div>
        <div class="metric-detail">Users reporting access issues from verification</div>
      </div>
      <div class="metric-hero">
        <div class="metric-value">&lt; 150ms</div>
        <div class="metric-label">Added Page-Load Latency</div>
        <div class="metric-detail">Average overhead for verified sessions</div>
      </div>
    </div>
    <table class="ba-table">
      <thead>
        <tr><th>Metric</th><th>Before Mitigation</th><th>After Mitigation</th></tr>
      </thead>
      <tbody>
        <tr><td>Scraping attempts per day</td><td>~1.2 million</td><td>~180,000</td></tr>
        <tr><td>Avg. origin server load (CPU)</td><td>78%</td><td>42%</td></tr>
        <tr><td>Legitimate user complaints (monthly)</td><td>1,200</td><td>340</td></tr>
        <tr><td>Uptime during bot surges</td><td>98.5%</td><td>99.97%</td></tr>
      </tbody>
    </table>
  </div>

  <!-- 4. TRADE-OFFS -->
  <div class="tradeoffs-section">
    <div class="section-title">
      <span class="num">4</span> Usability vs. Security Trade-offs
    </div>
    <div class="tradeoffs-grid">
