const path = require('path');

(async () => {
  const browser = await puppeteer.launch({
    headless: 'new',
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage', '--font-render-hinting=none']
  });
  const page = await browser.newPage();
  await page.setViewport({ width: 2384, height: 3370, deviceScaleFactor: 1 });
  await page.goto('file://' + path.resolve('/app/output/poster.html'), { waitUntil: 'networkidle0', timeout: 30000 });
  await page.waitForTimeout(2000);
  await page.screenshot({
    path: '/app/output/final_poster.png',
    type: 'png',
    fullPage: false,
    clip: { x: 0, y: 0, width: 2384, height: 3370 }
  });
  console.log('Screenshot saved to /app/output/final_poster.png');
  await browser.close();
})();

